const COVERAGE_SCHEMA = "andrii-candidate-answer-coverage-v1";

function clean(value) {
  return String(value || "").replace(/\s+/gu, " ").trim();
}

function key(value) {
  return clean(value).toLocaleLowerCase();
}

function markdownCell(value) {
  return clean(value)
    .replace(/\|/gu, "\\|")
    .replace(/\r?\n/gu, " ");
}

/**
 * Render a comparison section only from a complete, verified candidate-answer
 * artifact. The prose in each cell is generated by the answer-chapter stage;
 * this module only groups it by question and formats the markdown table.
 */
export function buildCandidateResponseTable({ answers = [], coverage = {} } = {}) {
  if (coverage?.schema !== COVERAGE_SCHEMA || coverage?.pass !== true) return "";
  const candidates = Array.isArray(coverage.expected_candidates)
    ? coverage.expected_candidates.map(clean).filter(Boolean)
    : [];
  const questions = Array.isArray(coverage.questions) ? coverage.questions : [];
  if (candidates.length < 2 || !questions.length || !Array.isArray(answers)) return "";

  const normalizedAnswers = answers
    .map((answer) => ({
      questionId: clean(answer?.question_id),
      candidate: clean(answer?.candidate),
      summary: clean(answer?.summary),
    }))
    .filter((answer) => answer.questionId && answer.candidate && answer.summary);

  const sections = [];
  for (const [index, question] of questions.entries()) {
    const questionId = clean(question?.question_id);
    const questionTitle = clean(question?.title);
    if (!questionId || !questionTitle) return "";
    const rows = [];
    for (const candidate of candidates) {
      const summaries = normalizedAnswers
        .filter((answer) => answer.questionId === questionId && key(answer.candidate) === key(candidate))
        .map((answer) => answer.summary)
        .filter((summary, summaryIndex, all) => all.indexOf(summary) === summaryIndex);
      // A complete coverage report must not be allowed to produce an empty
      // comparison cell when the answer summary itself is missing.
      if (!summaries.length) return "";
      rows.push(`| ${markdownCell(candidate)} | ${markdownCell(summaries.join(" "))} |`);
    }
    sections.push([
      `### ${index + 1}. ${questionTitle}`,
      "",
      "| Candidate | Response summary |",
      "| --- | --- |",
      ...rows,
    ].join("\n"));
  }

  return [
    "## Candidate Response Comparison",
    "",
    "The following tables summarize each candidate's verified response to each question. Repeated follow-ups within one question are combined in that candidate's cell.",
    "",
    sections.join("\n\n"),
  ].join("\n");
}

export { COVERAGE_SCHEMA as CANDIDATE_RESPONSE_COVERAGE_SCHEMA };
